package net.civeira.phylax.feature.notification.message.domain.valueholder;

import java.time.LocalDateTime;
import java.time.ZoneId;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.message.domain.Message;
import net.civeira.phylax.feature.notification.message.domain.valueobject.SendAtVO;

class SendAtValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of send at of message")
  void test_send_at_value_holder_assign_plain_value() {
    Object holder = new Object();
    SendAtValueHolder<Object> value = new SendAtValueHolder<>(holder);
    Assertions.assertSame(holder, value.sendAt(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime()),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSendAtValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime(),
        value.getSendAt().orElse(null), "The plain value must be recovered");
    Assertions.assertSame(holder, value.sendAtNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getSendAtValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getSendAt().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of send at of message")
  void test_send_at_value_holder_assign_value_object() {
    Object holder = new Object();
    SendAtValueHolder<Object> value = new SendAtValueHolder<>(holder);
    SendAtVO vo = SendAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Assertions.assertFalse(value.getSendAtValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.sendAt(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSendAtValue().orElseThrow());
    Assertions.assertSame(holder, value.sendAt(Optional.empty()));
    Assertions.assertFalse(value.getSendAtValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.sendAt(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSendAtValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of send at of message against the original")
  void test_send_at_value_holder_read() {
    Object holder = new Object();
    SendAtValueHolder<Object> value = new SendAtValueHolder<>(holder);
    SendAtVO vo = SendAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    SendAtVO other = SendAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    Message original = Mockito.mock(Message.class);
    Mockito.when(original.getSendAtValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSendAt(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSendAt(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.sendAt(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSendAt(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSendAt(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of send at of message")
  void test_send_at_value_holder_unset() {
    Object holder = new Object();
    SendAtValueHolder<Object> value = new SendAtValueHolder<>(holder);
    SendAtVO vo = SendAtVO.from(
        LocalDateTime.of(1980, 8, 20, 0, 0).atZone(ZoneId.of("Europe/Madrid")).toOffsetDateTime());
    value.sendAt(vo);
    Assertions.assertSame(holder, value.unsetSendAtIfMatches("sendAt_other"));
    Assertions.assertTrue(value.getSendAtValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSendAtIfMatches("sendAt"));
    Assertions.assertFalse(value.getSendAtValue().isPresent(),
        "The field name must clear the value");
    value.sendAt(vo);
    Assertions.assertSame(holder, value.unsetSendAt());
    Assertions.assertFalse(value.getSendAtValue().isPresent(), "Unset must clear the value");
  }
}
